mapper.select:
SELECT
FROM logical_product p LEFT JOIN product_capability pc ON pc.product_code = p.product_code WHERE 1=1
GROUP BY p.id,p.product_code,p.name,p.product_type,p.access_mode,p.default_country,p.default_currency,p.description,p.statement_descriptor,p.status,p.created_at,p.updated_at ORDER BY p.updated_at DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE logical_product
SET status=#{status},updated_at=#{now}
WHERE product_code=#{productCode}
